function showDuplicatePDFModal(warnings) {
    const warningsList = warnings.map(w => `
        <div class="duplicate-warning-item">
            <div class="warning-icon">
                <i class="fas fa-exclamation-triangle"></i>
            </div>
            <div class="warning-content">
                <h4>${escapeHtmlText(w.filename)}</h4>
                <p>This PDF was already uploaded as <strong>${escapeHtmlText(w.existing_course_name)}</strong></p>
                <div class="duplicate-actions">
                    <button class="btn btn-primary" onclick="viewExistingCourse('${escapeJsSingleQuoted(w.existing_course_id)}')">
                        <i class="fas fa-eye"></i> View Existing Modules
                    </button>
                    <button class="btn btn-secondary" onclick="proceedWithNewGeneration('${escapeJsSingleQuoted(w.filename)}', '${escapeJsSingleQuoted(w.pdf_hash)}')">
                        <i class="fas fa-redo"></i> Generate New Anyway
                    </button>
                </div>
            </div>
        </div>
    `).join('');
    
    const modal = `
        <div class="modal-overlay" id="duplicate-pdf-modal">
            <div class="modal-container" style="max-width: 700px;">
                <div class="modal-header">
                    <h2><i class="fas fa-copy"></i> Duplicate PDF Detected</h2>
                    <button class="btn-icon" onclick="closeDuplicatePDFModal()">&times;</button>
                </div>
                <div class="modal-content">
                    <div class="info-banner">
                        <i class="fas fa-info-circle"></i>
                        <p>The following PDF(s) have already been uploaded. You can view the existing modules or generate new ones.</p>
                    </div>
                    ${warningsList}
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" onclick="closeDuplicatePDFModal()">Cancel</button>
                </div>
            </div>
        </div>
    `;
    
    document.body.insertAdjacentHTML('beforeend', modal);
}

function viewExistingCourse(courseId) {
    closeDuplicatePDFModal();
    // Navigate to My Modules page
    const kbNavItem = document.querySelector('[data-view="kb"]');
    if (kbNavItem) {
        kbNavItem.click();
    }
    if (window.showNotification) {
        window.showNotification('Showing existing modules...', 'info');
    }
}

function proceedWithNewGeneration(filename, pdfHash) {
    closeDuplicatePDFModal();
    const message = 'Please upload new files to generate new modules.';
    if (window.showNotification) {
        window.showNotification(message, 'info');
    } else {
        alert(message);
    }
}

function closeDuplicatePDFModal() {
    const modal = document.getElementById('duplicate-pdf-modal');
    if (modal) modal.remove();
}

// ---------------------------------------------------------------------------
// SHARED INTERACTIVE CHART HELPERS (Canvas, no external libs)
// ---------------------------------------------------------------------------

/**
 * Draw an interactive donut chart on a canvas element.
 * Hover shows tooltip with label, value, percentage.
 * Hovered slice expands outward.
 */
function computeDonutPercentages(values, total) {
    const safeTotal = total || values.reduce((sum, value) => sum + value, 0) || 1;
    const exact = values.map((value) => (value / safeTotal) * 100);
    const floors = exact.map((value) => Math.floor(value));
    let remainder = 100 - floors.reduce((sum, value) => sum + value, 0);
    const order = exact
        .map((value, index) => ({ index, fraction: value - floors[index] }))
        .sort((a, b) => b.fraction - a.fraction);
    const percentages = [...floors];
    for (let i = 0; i < remainder; i += 1) {
        percentages[order[i % order.length].index] += 1;
    }
    return percentages;
}

function drawInteractiveDonut(canvasId, slices, total, unit) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const cx = W / 2, cy = H / 2;
    const R = Math.min(W, H) / 2 - 10;
    const innerR = R * 0.52;
    const COLORS = ['#a78bfa','#38bdf8','#34d399','#fb923c','#f472b6','#d97706','#60a5fa'];
    const realTotal = total || slices.reduce((s, x) => s + x.value, 0) || 1;
    const unitLabel = unit || 'tokens';

    // assign colors if not set
    slices.forEach((s, i) => { if (!s.color) s.color = COLORS[i % COLORS.length]; });

    // build arc data
    let startAngle = -Math.PI / 2;
    const arcs = slices.map(sl => {
        const sweep = (sl.value / realTotal) * 2 * Math.PI;
        const arc = { ...sl, startAngle, sweep, endAngle: startAngle + sweep };
        startAngle += sweep;
        return arc;
    });

    let hoveredIdx = -1;
    let tooltip = null;

    function hexToRgb(hex) {
        const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
        return `${r},${g},${b}`;
    }

    function draw(hIdx) {
        ctx.clearRect(0, 0, W, H);

        arcs.forEach((arc, i) => {
            const expand = (i === hIdx) ? 8 : 0;
            const midAngle = arc.startAngle + arc.sweep / 2;
            const ox = Math.cos(midAngle) * expand;
            const oy = Math.sin(midAngle) * expand;

            // glow on hover
            if (i === hIdx) {
                ctx.shadowColor = arc.color;
                ctx.shadowBlur = 18;
            } else {
                ctx.shadowBlur = 0;
            }

            ctx.beginPath();
            ctx.moveTo(cx + ox, cy + oy);
            ctx.arc(cx + ox, cy + oy, R, arc.startAngle, arc.endAngle);
            ctx.closePath();
            ctx.fillStyle = (i === hIdx) ? arc.color : arc.color + 'cc';
            ctx.fill();
            ctx.shadowBlur = 0;

            // percentage label on slice if big enough
            const pct = Math.round(arc.sweep / (2 * Math.PI) * 100);
            if (pct >= 8) {
                const lx = cx + ox + Math.cos(midAngle) * (R * 0.72);
                const ly = cy + oy + Math.sin(midAngle) * (R * 0.72);
                ctx.fillStyle = '#fff';
                ctx.font = `bold ${pct >= 15 ? 13 : 11}px sans-serif`;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(pct + '%', lx, ly);
            }
        });

        // inner hole (light theme)
        ctx.beginPath();
        ctx.arc(cx, cy, innerR, 0, 2 * Math.PI);
        ctx.fillStyle = '#ffffff';
        ctx.fill();
        ctx.strokeStyle = '#e6e9ef';
        ctx.lineWidth = 1;
        ctx.stroke();

        // center text
        if (hIdx >= 0) {
            const a = arcs[hIdx];
            const pct = Math.round(a.sweep / (2 * Math.PI) * 100);
            ctx.fillStyle = a.color;
            ctx.font = `bold 18px sans-serif`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(pct + '%', cx, cy - 10);
            ctx.fillStyle = '#475569';
            ctx.font = '11px sans-serif';
            ctx.fillText(a.label, cx, cy + 10);
        } else {
            const topSlice = arcs.reduce((m, a) => a.sweep > m.sweep ? a : m, arcs[0] || { sweep: 0, label: '', color: '#2563eb' });
            const pct = topSlice ? Math.round(topSlice.sweep / (2 * Math.PI) * 100) : 0;
            ctx.fillStyle = topSlice ? topSlice.color : '#2563eb';
            ctx.font = 'bold 18px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(pct + '%', cx, cy - 10);
            ctx.fillStyle = '#475569';
            ctx.font = '11px sans-serif';
            ctx.fillText(topSlice ? topSlice.label : '', cx, cy + 10);
        }
    }

    function getHovered(mx, my) {
        const dx = mx - cx, dy = my - cy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < innerR || dist > R + 12) return -1;
        let angle = Math.atan2(dy, dx);
        if (angle < -Math.PI / 2) angle += 2 * Math.PI;
        for (let i = 0; i < arcs.length; i++) {
            let s = arcs[i].startAngle, e = arcs[i].endAngle;
            if (s < -Math.PI/2) { s += 2*Math.PI; e += 2*Math.PI; }
            if (angle >= s && angle <= e) return i;
        }
        return -1;
    }

    // tooltip element
    function showTooltip(arc, x, y) {
        if (!tooltip) {
            tooltip = document.createElement('div');
            tooltip.style.cssText = 'position:fixed;background:rgba(15,23,42,0.95);border:1px solid rgba(255,255,255,0.15);border-radius:8px;padding:8px 12px;font-size:12px;color:var(--text-secondary);pointer-events:none;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.5);transition:opacity 0.15s;';
            document.body.appendChild(tooltip);
        }
        const pct = Math.round(arc.sweep / (2 * Math.PI) * 100);
        tooltip.innerHTML = `<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${arc.color};margin-right:6px;"></span><strong>${arc.label}</strong><br><span style="color:rgba(255,255,255,0.7);">${arc.value.toLocaleString()} ${unitLabel} &bull; ${pct}%</span>`;
        tooltip.style.left = (x + 12) + 'px';
        tooltip.style.top  = (y - 10) + 'px';
        tooltip.style.opacity = '1';
    }

    function hideTooltip() {
        if (tooltip) { tooltip.style.opacity = '0'; setTimeout(() => { if (tooltip) { tooltip.remove(); tooltip = null; } }, 150); }
    }

    canvas.addEventListener('mousemove', e => {
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width, scaleY = canvas.height / rect.height;
        const mx = (e.clientX - rect.left) * scaleX;
        const my = (e.clientY - rect.top) * scaleY;
        const idx = getHovered(mx, my);
        if (idx !== hoveredIdx) { hoveredIdx = idx; draw(hoveredIdx); }
        if (idx >= 0) showTooltip(arcs[idx], e.clientX, e.clientY);
        else hideTooltip();
    });
    canvas.addEventListener('mouseleave', () => { hoveredIdx = -1; draw(-1); hideTooltip(); });

    // build legend
    const legendId = canvasId + '-legend';
    const legendEl = document.getElementById(legendId);
    if (legendEl) {
        const legendPercents = computeDonutPercentages(
            arcs.map((arc) => arc.value),
            realTotal
        );
        legendEl.innerHTML = arcs.map((arc, index) => {
            const pct = legendPercents[index];
            return `<span style="font-size:11px;color:var(--text-primary);display:flex;align-items:center;gap:4px;cursor:default;" title="${arc.value.toLocaleString()} ${unitLabel}"><span style="width:10px;height:10px;border-radius:50%;background:${arc.color};display:inline-block;flex-shrink:0;"></span>${arc.label}: <strong style="color:${arc.color}">${arc.value}</strong> <span style="color:var(--text-secondary)">(${pct}%)</span></span>`;
        }).join('');
    }

    draw(-1);
}

/**
 * Render interactive HTML bar-card list (replaces canvas bars).
 * canvasId can be a canvas element id OR a container div id.
 * Renders sibling div next to canvas (or replaces canvas with div).
 */
function drawInteractiveBars(canvasId, bars, options = {}) {
    let target = document.getElementById(canvasId);
    if (!target) return;

    // Replace canvas with div if needed
    if (target.tagName === 'CANVAS') {
        const div = document.createElement('div');
        div.id = canvasId;
        target.parentNode.replaceChild(div, target);
        target = div;
    }

    target.className = 'ibar-list';
    target.innerHTML = '';

    if (!bars || !bars.length) {
        target.innerHTML = '<div class="sysstat-muted" style="font-size:12px;padding:8px 0">No data</div>';
        return;
    }

    const maxVal = Math.max(...bars.map(b => b.value), 1);
    const COLORS = ['#a78bfa','#38bdf8','#34d399','#fb923c','#f472b6','#d97706','#60a5fa','#e879f9'];
    bars.forEach((b, i) => { if (!b.color) b.color = COLORS[i % COLORS.length]; });

    bars.forEach(bar => {
        const rawPct = Math.round(bar.value / maxVal * 100);
        const pct = bar.value === 0 ? 0 : Math.max(2, rawPct);
        const row = document.createElement('div');
        row.className = 'ibar-row';
        if (bar.onclick) {
            row.style.cursor = 'pointer';
            // setAttribute does not HTML-decode, so callers escape bar.onclick
            // arguments for the JS string-literal context only (escapeJsSingleQuoted).
            row.setAttribute('onclick', bar.onclick);
        }
        const clickHint = bar.onclick ? ` <span style="font-size:10px;font-weight:400;color:var(--text-muted)">&#9432;</span>` : '';
        const safeColor = sanitizeCssColor(bar.color);
        row.innerHTML = `
            <div class="ibar-header">
                <span class="ibar-label">${escapeHtmlText(bar.label)}</span>
                <span class="ibar-val" style="color:${safeColor}">${escapeHtmlText(Number(bar.value || 0).toLocaleString())}${clickHint}</span>
            </div>
            <div class="ibar-track">
                <div class="ibar-fill" style="width:${pct}%;background:linear-gradient(90deg,${safeColor},${safeColor}88)">
                    <span class="ibar-pct">${pct}%</span>
                </div>
            </div>`;
        row.addEventListener('mouseenter', () => row.classList.add('ibar-row--hov'));
        row.addEventListener('mouseleave', () => row.classList.remove('ibar-row--hov'));
        target.appendChild(row);
    });
}

// === 2. TOKEN ANALYTICS (TRAINER) ===

async function loadTokenAnalytics() {
    const container = document.getElementById('token-analytics-content');
    if (!container) {
        console.error('Token analytics container not found');
        return;
    }
    
    container.innerHTML = '<div class="loading-state"><i class="fas fa-spinner fa-spin"></i><p>Loading token analytics...</p></div>';
    
    try {
        const authToken = window.authToken || localStorage.getItem('authToken');
        const API_BASE_URL = window.location.origin;
        
        if (!authToken) {
            throw new Error('Not authenticated');
        }
        
        const response = await fetch(`${API_BASE_URL}/trainer/token-analytics`, {
            headers: {
                'Authorization': `Bearer ${authToken}`,
                'Content-Type': 'application/json'
            }
        });
        
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        
        const result = await response.json();
        
        if (result.success) {
            renderTokenAnalytics(result);
        } else {
            container.innerHTML = `
                <div class="empty-state">
                    <i class="fas fa-chart-line"></i>
                    <h3>No Token Data</h3>
                    <p>No token usage data available yet.</p>
                </div>
            `;
        }
    } catch (error) {
        console.error('Error loading token analytics:', error);
        container.innerHTML = `
            <div class="empty-state">
                <i class="fas fa-exclamation-circle"></i>
                <h3>Error Loading Analytics</h3>
                <p>${escapeHtmlText(error.message || 'Failed to load token analytics')}</p>
                <button class="btn btn-primary" onclick="loadTokenAnalytics()">
                    <i class="fas fa-sync"></i> Retry
                </button>
            </div>
        `;
    }
}

function renderTokenAnalytics(data) {
    const container = document.getElementById('token-analytics-content');

    // -- helpers --------------------------------------------------------------
    function tkDonut(slices, cx, cy, r) {
        const total = slices.reduce((s, x) => s + x.value, 0);
        if (total === 0) return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="rgba(255,255,255,0.08)"/>`;
        let angle = -Math.PI / 2, paths = '';
        slices.forEach(sl => {
            const sweep = (sl.value / total) * 2 * Math.PI;
            const x1 = cx + r * Math.cos(angle), y1 = cy + r * Math.sin(angle);
            const x2 = cx + r * Math.cos(angle + sweep), y2 = cy + r * Math.sin(angle + sweep);
            const large = sweep > Math.PI ? 1 : 0;
            paths += `<path d="M${cx},${cy} L${x1},${y1} A${r},${r} 0 ${large},1 ${x2},${y2} Z" fill="${sl.color}" opacity="0.9"/>`;
            angle += sweep;
        });
        return paths + `<circle cx="${cx}" cy="${cy}" r="${r * 0.55}" fill="var(--card-bg,#1a2035)"/>`;
    }

    // -- data prep ---------------------------------------------------------
    const courseTokens = data.courses.reduce((sum, c) => sum + c.tokens_used, 0);
    const nonCourseTokens = data.total_tokens - courseTokens;

    let nonCourseModuleGen = 0, nonCourseModuleVision = 0, nonCourseTutor = 0, nonCourseChat = 0;
    if (data.usage_details) {
        data.usage_details.forEach(record => {
            if (!record.course_id || record.course_id === 'null') {
                if (record.operation_type === 'module_generation') nonCourseModuleGen += record.tokens_used;
                else if (record.operation_type === 'module_vision') nonCourseModuleVision += record.tokens_used;
                else if (record.operation_type === 'tutor_query') nonCourseTutor += record.tokens_used;
                else if (record.operation_type === 'chat_agent') nonCourseChat += record.tokens_used;
            }
        });
    }

    const ops = data.operations || {};
    const courseModText = data.courses.reduce((s, c) => s + (c.module_text_tokens || 0), 0);
    const courseModVision = data.courses.reduce((s, c) => s + (c.module_vision_tokens || 0), 0);
    const courseModGen = data.courses.reduce((s, c) => s + (c.module_gen_tokens || 0), 0);
    const courseTutor  = data.courses.reduce((s, c) => s + (c.tutor_queries_tokens || 0), 0);
    const courseChat   = data.courses.reduce((s, c) => s + (c.chat_agent_tokens || 0), 0);

    let totalModText = ops.module_text != null ? ops.module_text : (courseModText + nonCourseModuleGen);
    let totalModVision = ops.module_vision != null ? ops.module_vision : (courseModVision + nonCourseModuleVision);
    let totalModGen = ops.module_generation != null ? ops.module_generation : (totalModText + totalModVision);
    let totalTutor = ops.tutor_query != null ? ops.tutor_query : (courseTutor + nonCourseTutor);
    let totalChat = ops.chat_agent != null ? ops.chat_agent : (courseChat + nonCourseChat);

    const opSum = totalModGen + totalTutor + totalChat;
    if (opSum !== data.total_tokens && ops.module_generation == null) {
        totalChat = Math.max(0, data.total_tokens - totalModGen - totalTutor);
    }
    const nonCourseModuleTotal = nonCourseModuleGen + nonCourseModuleVision;
    const nonCourseOpSum = nonCourseModuleTotal + nonCourseTutor + nonCourseChat;
    if (nonCourseOpSum !== nonCourseTokens && ops.module_generation == null) {
        nonCourseChat = Math.max(0, nonCourseTokens - nonCourseModuleTotal - nonCourseTutor);
    }

    const top5 = [...data.courses].sort((a, b) => b.tokens_used - a.tokens_used).slice(0, 5);
    const maxCourseTokens = top5.length ? top5[0].tokens_used : 1;

    const donut1Slices = [
        { value: courseTokens,    color: '#667eea', label: 'Course' },
        { value: nonCourseTokens, color: '#f093fb', label: 'Non-Course' }
    ];
    const donut1Pct = data.total_tokens > 0 ? Math.round(courseTokens / data.total_tokens * 100) : 0;

    const donut2Slices = totalModVision > 0 ? [
        { value: totalModText, color: '#4facfe', label: 'Module Text' },
        { value: totalModVision, color: '#818cf8', label: 'Module Vision' },
        { value: totalTutor,  color: '#43e97b', label: 'Tutor' },
        { value: totalChat,   color: '#f5576c', label: 'Chat Agent' }
    ] : [
        { value: totalModGen, color: '#4facfe', label: 'Module Gen' },
        { value: totalTutor,  color: '#43e97b', label: 'Tutor' },
        { value: totalChat,   color: '#f5576c', label: 'Chat Agent' }
    ];

    const opColors = { 'Module Gen': '#4facfe', 'Tutor Queries': '#43e97b', 'Chat Agent': '#f5576c' };
    const maxOp = Math.max(totalModGen, totalTutor, totalChat, 1);
    const courseBarColors = ['#667eea','#4facfe','#43e97b','#f093fb','#f5576c'];

    const html = `
        <div class="token-analytics-dashboard">
            <!-- Summary cards -->
            <div class="token-summary-cards">
                <div class="summary-card tokens-card">
                    <div class="card-icon"><i class="fas fa-coins"></i></div>
                    <div class="card-content">
                        <h3>${data.total_tokens.toLocaleString()}</h3>
                        <p>Total Tokens Used</p>
                        <small>Courses: ${courseTokens.toLocaleString()} | Other: ${nonCourseTokens.toLocaleString()}${totalModVision > 0 ? ` | Vision: ${totalModVision.toLocaleString()}` : ''}</small>
                    </div>
                </div>
                <div class="summary-card cost-card">
                    <div class="card-icon"><i class="fas fa-dollar-sign"></i></div>
                    <div class="card-content">
                        <h3>$${data.total_cost_dollars.toFixed(2)}</h3>
                        <p>Total Cost</p>
                    </div>
                </div>
                <div class="summary-card courses-card">
                    <div class="card-icon"><i class="fas fa-book"></i></div>
                    <div class="card-content">
                        <h3>${data.courses.length}</h3>
                        <p>Courses Generated</p>
                    </div>
                </div>
            </div>

            <!-- -- CHARTS ROW -- -->
            <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin:24px 0;">
                <div style="padding:20px;background:var(--card-bg);border:1px solid var(--border-color);border-radius:12px;display:flex;flex-direction:column;align-items:center;">
                    <div style="font-weight:600;margin-bottom:12px;font-size:13px;color:var(--text-primary);"><i class="fas fa-chart-pie" style="color:#a78bfa;margin-right:6px;"></i>Token Distribution</div>
                    <canvas id="tk-donut1" width="200" height="200" style="cursor:pointer;max-width:200px;"></canvas>
                    <div id="tk-donut1-legend" style="display:flex;gap:10px;margin-top:10px;flex-wrap:wrap;justify-content:center;"></div>
                </div>
                <div style="padding:20px;background:var(--card-bg);border:1px solid var(--border-color);border-radius:12px;display:flex;flex-direction:column;align-items:center;">
                    <div style="font-weight:600;margin-bottom:12px;font-size:13px;color:var(--text-primary);"><i class="fas fa-layer-group" style="color:#38bdf8;margin-right:6px;"></i>By Operation Type</div>
                    <canvas id="tk-donut2" width="200" height="200" style="cursor:pointer;max-width:200px;"></canvas>
                    <div id="tk-donut2-legend" style="display:flex;gap:10px;margin-top:10px;flex-wrap:wrap;justify-content:center;"></div>
                </div>
                <div style="padding:20px;background:var(--card-bg);border:1px solid var(--border-color);border-radius:12px;overflow:hidden;">
                    <div style="font-weight:600;margin-bottom:16px;font-size:13px;color:var(--text-primary);"><i class="fas fa-chart-bar" style="color:#34d399;margin-right:6px;"></i>Operation Totals</div>
                    <canvas id="tk-opbars" width="600" height="10" style="width:100%;cursor:pointer;display:block;"></canvas>
                </div>
            </div>
            ${top5.length > 0 ? `
            <div style="padding:20px;background:var(--card-bg);border:1px solid var(--border-color);border-radius:12px;margin-bottom:24px;">
                <div style="font-weight:600;margin-bottom:16px;font-size:13px;color:var(--text-primary);"><i class="fas fa-trophy" style="color:#d97706;margin-right:6px;"></i>Top Courses by Token Usage</div>
                <div id="tk-top-courses-list"></div>
            </div>
            ` : ''}
            <!-- Non-course usage note -->
            ${nonCourseTokens > 0 ? `
                <div class="token-course-breakdown" style="margin-bottom: 24px;">
                    <h3><i class="fas fa-info-circle"></i> Non-Course Token Usage</h3>
                    <div style="padding: 16px; background: rgba(255, 193, 7, 0.1); border: 1px solid rgba(255, 193, 7, 0.3); border-radius: 8px;">
                        <p style="margin-bottom: 12px; color: var(--text-primary);">
                            <strong>${nonCourseTokens.toLocaleString()} tokens</strong> were used outside of specific courses:
                        </p>
                        <div style="display: flex; gap: 16px; flex-wrap: wrap;">
                            ${nonCourseTutor > 0 ? `<div style="flex:1;min-width:150px;"><div style="font-size:20px;font-weight:bold;color:#2563eb;">${nonCourseTutor.toLocaleString()}</div><div style="font-size:12px;color:var(--text-secondary);">Tutor Queries</div></div>` : ''}
                            ${nonCourseChat > 0 ? `<div style="flex:1;min-width:150px;"><div style="font-size:20px;font-weight:bold;color:#16a34a;">${nonCourseChat.toLocaleString()}</div><div style="font-size:12px;color:var(--text-secondary);">Chat Agent</div></div>` : ''}
                            ${nonCourseModuleGen > 0 ? `<div style="flex:1;min-width:150px;"><div style="font-size:20px;font-weight:bold;color:#9333ea;">${nonCourseModuleGen.toLocaleString()}</div><div style="font-size:12px;color:var(--text-secondary);">Module Text</div></div>` : ''}
                            ${nonCourseModuleVision > 0 ? `<div style="flex:1;min-width:150px;"><div style="font-size:20px;font-weight:bold;color:#818cf8;">${nonCourseModuleVision.toLocaleString()}</div><div style="font-size:12px;color:var(--text-secondary);">Module Vision</div></div>` : ''}
                        </div>
                    </div>
                </div>
            ` : ''}

            <!-- Full course table -->
            <div class="token-course-breakdown">
                <h3><i class="fas fa-list"></i> Course Breakdown</h3>
                ${data.courses.length > 0 ? `
                    <div class="table-container">
                        <table class="token-table">
                            <thead>
                                <tr>
                                    <th>Course Name</th>
                                    <th>Total Tokens</th>
                                    <th>Cost</th>
                                    <th>Module Text</th>
                                    <th>Module Vision</th>
                                    <th>Tutor Queries</th>
                                    <th>Chat Agent</th>
                                    <th>Created</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${data.courses.map(course => `
                                    <tr>
                                        <td><i class="fas fa-file-pdf"></i> ${escapeHtmlText(course.course_title || course.course_name || 'Untitled')}</td>
                                        <td>${course.tokens_used.toLocaleString()}</td>
                                        <td>$${(course.cost_cents / 100).toFixed(3)}</td>
                                        <td>${(course.module_text_tokens || course.module_gen_tokens || 0).toLocaleString()}</td>
                                        <td>${(course.module_vision_tokens || 0).toLocaleString()}</td>
                                        <td>${course.tutor_queries_tokens.toLocaleString()}</td>
                                        <td>${course.chat_agent_tokens.toLocaleString()}</td>
                                        <td>${formatDateIST(course.created_at)}</td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                    </div>
                ` : `<div class="empty-state"><i class="fas fa-inbox"></i><p>No courses generated yet</p></div>`}
            </div>
        </div>
    `;

    container.innerHTML = html;

    // -- Draw interactive Canvas charts ------------------------------------
    setTimeout(() => {
        drawInteractiveDonut('tk-donut1', donut1Slices, data.total_tokens);
        drawInteractiveDonut('tk-donut2', donut2Slices, data.total_tokens);
        drawInteractiveBars('tk-opbars', totalModVision > 0 ? [
            { label: 'Module Text', value: totalModText, color: '#38bdf8' },
            { label: 'Module Vision', value: totalModVision, color: '#818cf8' },
            { label: 'Tutor Queries', value: totalTutor, color: '#34d399' },
            { label: 'Chat Agent', value: totalChat, color: '#fb923c' }
        ] : [
            { label: 'Module Gen',    value: totalModGen, color: '#38bdf8' },
            { label: 'Tutor Queries', value: totalTutor,  color: '#34d399' },
            { label: 'Chat Agent',    value: totalChat,   color: '#fb923c' }
        ]);

        // -- Top Courses HTML cards ----------------------------------------
        const topCoursesEl = document.getElementById('tk-top-courses-list');
        if (topCoursesEl && top5.length > 0) {
            const cColors = ['#a78bfa','#38bdf8','#34d399','#fb923c','#f472b6'];
            const cRanks  = ['1','2','3','4','5'];
            topCoursesEl.innerHTML = top5.map((c, i) => {
                const pct = Math.round(c.tokens_used / maxCourseTokens * 100);
                const col = cColors[i];
                const name = escapeHtmlText(c.course_title || c.course_name || 'Untitled');
                return `
                <div class="vb-rich-card" style="margin-bottom:12px;padding:14px 16px;border-radius:10px;transition:background 0.2s,border-color 0.2s;cursor:default;">
                    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px;gap:12px;">
                        <div style="display:flex;align-items:flex-start;gap:8px;min-width:0;flex:1;">
                            <span style="font-size:11px;font-weight:700;flex-shrink:0;width:22px;height:22px;border-radius:50%;background:${col}33;color:${col};border:1px solid ${col}66;display:flex;align-items:center;justify-content:center;">${cRanks[i]}</span>
                            <span style="font-size:13px;font-weight:600;color:var(--text-primary);line-height:1.4;word-break:break-word;">${name}</span>
                        </div>
                        <div style="text-align:right;flex-shrink:0;">
                            <div style="font-size:16px;font-weight:700;color:${col};">${c.tokens_used.toLocaleString()}</div>
                            <div class="vb-unit-label" style="font-size:10px;">tokens &bull; ${pct}%</div>
                        </div>
                    </div>
                    <div class="vb-bar-track" style="border-radius:6px;height:7px;overflow:hidden;margin-bottom:8px;">
                        <div style="width:${pct}%;height:100%;background:linear-gradient(90deg,${col},${col}77);border-radius:6px;"></div>
                    </div>
                    <div style="display:flex;gap:16px;flex-wrap:wrap;">
                        <span class="tk-detail-stat"><span class="tk-stat-blue">${(c.module_text_tokens || c.module_gen_tokens || 0).toLocaleString()}</span> Text</span>
                        <span class="tk-detail-stat"><span style="color:#818cf8;font-weight:600;">${(c.module_vision_tokens||0).toLocaleString()}</span> Vision</span>
                        <span class="tk-detail-stat"><span class="tk-stat-green">${(c.tutor_queries_tokens||0).toLocaleString()}</span> Tutor</span>
                        <span class="tk-detail-stat"><span class="tk-stat-orange">${(c.chat_agent_tokens||0).toLocaleString()}</span> Chat</span>
                        <span class="tk-detail-stat" style="margin-left:auto;"><span class="tk-stat-amber">$${(c.cost_cents/100).toFixed(3)}</span></span>
                    </div>
                </div>`;
            }).join('');
        }
    }, 50);
}




// === 3. SUPER ADMIN TOKEN ANALYTICS ===

async function loadAdminTokenAnalytics() {
    const container = document.getElementById('admin-token-analytics');
    if (!container) {
        console.error('Admin token analytics container not found');
        return;
    }
    
    // READ FILTER VALUES BEFORE CLEARING THE CONTAINER!
    const processFilterEl = document.getElementById('admin-token-process-filter');
    const roleFilterEl = document.getElementById('admin-token-role-filter');
    
    console.log('[TOKEN ANALYTICS] Filter elements:', { 
        processFilterEl: processFilterEl, 
        processValue: processFilterEl?.value,
        processOptions: processFilterEl ? Array.from(processFilterEl.options).map(o => ({value: o.value, text: o.text, selected: o.selected})) : null,
        roleFilterEl: roleFilterEl,
        roleValue: roleFilterEl?.value 
    });
    
    const processFilter = processFilterEl?.value || '';
    const roleFilter = roleFilterEl?.value || '';
    
    console.log('[TOKEN ANALYTICS] Applying filters:', { processFilter, roleFilter });
    
    // NOW clear the container and show loading state
    container.innerHTML = '<div class="loading-state admin-tab-loading"><i class="fas fa-spinner fa-spin"></i><p>Loading system token analytics...</p></div>';
    
    try {
        const authToken = window.authToken || localStorage.getItem('authToken');
        const API_BASE_URL = window.location.origin;
        
        if (!authToken) {
            throw new Error('Not authenticated');
        }
        
        let url = `${API_BASE_URL}/super-admin/token-analytics`;
        const params = new URLSearchParams();
        if (processFilter) params.append('process_id', processFilter);
        if (roleFilter) params.append('role', roleFilter);
        if (params.toString()) url += `?${params.toString()}`;
        
        console.log('[TOKEN ANALYTICS] Fetching URL:', url);
        
        const response = await fetch(url, {
            headers: {
                'Authorization': `Bearer ${authToken}`,
                'Content-Type': 'application/json'
            }
        });
        
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        
        const result = await response.json();
        
        if (result.success) {
            console.log('[TOKEN ANALYTICS] Data loaded:', { 
                trainers: result.trainers?.length || 0, 
                trainees: result.trainees?.length || 0 
            });
            // PASS THE FILTER VALUES TO THE RENDER FUNCTION
            renderAdminTokenAnalytics(result, processFilter, roleFilter);
        } else {
            container.innerHTML = '<div class="empty-state"><i class="fas fa-inbox"></i><p>No token usage data available yet</p></div>';
        }
    } catch (error) {
        console.error('Error loading admin token analytics:', error);
        container.innerHTML = `<div class="error-state"><i class="fas fa-exclamation-circle"></i><p>Failed to load token analytics: ${escapeHtmlText(error.message || 'Unknown error')}</p></div>`;
    }
}

function renderAdminTokenUserRows(users, iconClass = 'fa-user') {
    return users.map(user => {
        const ops = user.operations || {};
        const modText = ops.module_text != null ? ops.module_text : (ops.module_generation || 0);
        const modVision = ops.module_vision || 0;
        const modTotal = ops.module_generation != null ? ops.module_generation : (modText + modVision);
        const costCents = user.total_cost_cents || 0;
        const costDisplay = user.total_cost_dollars != null
            ? Number(user.total_cost_dollars).toFixed(3)
            : (costCents / 100).toFixed(3);
        return `
            <tr>
                <td><i class="fas ${iconClass}"></i> ${escapeHtmlText(user.email)}</td>
                <td>${escapeHtmlText(user.process || 'N/A')}</td>
                <td>${escapeHtmlText(user.role || 'N/A')}</td>
                <td>${user.total_tokens.toLocaleString()}</td>
                <td>$${costDisplay}</td>
                <td>${modText.toLocaleString()}</td>
                <td>${modVision.toLocaleString()}</td>
                <td>${modTotal.toLocaleString()}</td>
                <td>${(ops.tutor_query || 0).toLocaleString()}</td>
                <td>${(ops.chat_agent || 0).toLocaleString()}</td>
            </tr>
        `;
    }).join('');
}

