function toggleBatchSelectVisibility(show) {
    const container = document.getElementById('batch-select-container');
    if (container) {
        container.style.display = show ? 'block' : 'none';
    }
}

async function publishCourseEnhanced(courseName) {
    const authToken = window.authToken || localStorage.getItem('authToken');
    const API_BASE_URL = window.location.origin;
    
    const publishType = document.querySelector('input[name="publish-type"]:checked')?.value;
    
    if (!publishType) {
        if (window.showNotification) {
            window.showNotification('Please select a publication type', 'error');
        } else {
            alert('Please select a publication type');
        }
        return;
    }
    
    let batchId = null;
    if (publishType === 'batch') {
        batchId = document.getElementById('batch-select-enhanced')?.value;
        if (!batchId) {
            if (window.showNotification) {
                window.showNotification('Please select a batch', 'error');
            } else {
                alert('Please select a batch');
            }
            return;
        }
    }
    
    const publishSteps = [
        '📋 Step 1/5: Validating course modules & assessment config...',
        '💾 Step 2/5: Marking course live & caching metadata...',
        '👥 Step 3/5: Enrolling trainees & setting up attempts...',
        '🔔 Step 4/5: Sending notifications...',
        '✅ Step 5/5: Finishing publish (tutor cache continues in background)...'
    ];
    let stepIndex = 0;
    if (window.showLoader) window.showLoader(publishSteps[0]);
    const stepInterval = setInterval(() => {
        stepIndex = Math.min(stepIndex + 1, publishSteps.length - 1);
        if (window.showLoader) window.showLoader(publishSteps[stepIndex]);
    }, 5000);

    try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), PUBLISH_API_TIMEOUT_MS);
        let response;
        try {
            response = await fetch(`${API_BASE_URL}/trainer/publish-course-enhanced`, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${authToken}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    source_doc_name: courseName,
                    publication_type: publishType,
                    batch_id: batchId
                }),
                signal: controller.signal,
            });
        } finally {
            clearTimeout(timeoutId);
        }
        
        clearInterval(stepInterval);
        if (window.hideLoader) window.hideLoader();

        const responseText = await response.text();
        let result = {};
        try {
            result = responseText ? JSON.parse(responseText) : {};
        } catch (parseErr) {
            result = {};
        }
        
        if (response.ok && result.success) {
            const moduleCount = result.module_count || 0;
            const traineeCount = result.trainee_count || 0;
            const successMsg = moduleCount
                ? `✅ Course published — ${moduleCount} module(s) ready, ${traineeCount} trainee(s) enrolled. Tutor responses continue preparing in the background.`
                : (result.message || 'Course published successfully!');
            showNotification(successMsg, 'success');
            closeEnhancedPublishModal();
            // Refresh dashboard if function exists
            if (typeof refreshKBView === 'function') {
                refreshKBView();
            } else if (typeof window.refreshKBView === 'function') {
                window.refreshKBView();
            }
        } else if (response.status === 504 || response.status === 502) {
            showNotification(
                'Publish took longer than the gateway limit. Refreshing — if the course shows Published, it succeeded.',
                'warning'
            );
            if (typeof refreshKBView === 'function') {
                refreshKBView();
            } else if (typeof window.refreshKBView === 'function') {
                window.refreshKBView();
            }
        } else {
            const detail = result.detail || result.message || 'Failed to publish course';
            showNotification(typeof detail === 'string' ? detail : 'Failed to publish course', 'error');
        }
    } catch (err) {
        clearInterval(stepInterval);
        if (window.hideLoader) window.hideLoader();
        console.error('[PUBLISH] Enhanced publish error:', err);
        showNotification('Failed to publish course. Please try again.', 'error');
    }
}

function closeEnhancedPublishModal() {
    const modal = document.getElementById('enhanced-publish-modal');
    if (modal) modal.remove();
}

