async function indexAdminVideoReportForChat(historyId, trainerUserId, trainerEmail, isReindex = false) {
    if (!historyId) return;
    try {
        showNotification(
            isReindex
                ? 'Reindexing report for chat (trainer will be notified)...'
                : 'Indexing report for chat (trainer will be notified)...',
            'info',
        );
        const token = window.authToken || localStorage.getItem('authToken');
        const res = await fetch(`/video-analysis/index/${historyId}`, {
            method: 'POST',
            headers: { Authorization: `Bearer ${token}` },
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.detail || 'Indexing failed');
        const warning = data.data?.warning;
        let msg = isReindex
            ? 'Report reindexed for chat. The trainer has been notified.'
            : 'Report indexed for chat. The trainer has been notified.';
        showNotification(warning || msg, warning ? 'warning' : 'success');

        const openModal = document.querySelector('.modal-overlay[data-va-trainer-reports]');
        if (openModal && openModal.dataset.userId === trainerUserId) {
            openModal.remove();
        }
        await viewVideoAnalysisUserReports(trainerUserId, trainerEmail);
    } catch (err) {
        showNotification(`Indexing error: ${err.message}`, 'error');
    }
}

window.indexAdminVideoReportForChat = indexAdminVideoReportForChat;

async function downloadSuperAdminVideoAnalysisReport(historyId, reportTitle, exportFormat) {
    const format = (exportFormat || 'pdf').toLowerCase();
    const isDocx = format === 'docx';
    const endpoint = isDocx
        ? `/video-analysis/view-docx/${historyId}`
        : `/video-analysis/view-pdf/${historyId}`;
    const ext = isDocx ? 'docx' : 'pdf';

    const button = event?.target?.closest?.('.btn-secondary');
    const originalHTML = button ? button.innerHTML : '';

    try {
        if (button) {
            button.disabled = true;
            button.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
        }

        const token = window.authToken || localStorage.getItem('authToken');
        const response = await fetch(endpoint, {
            headers: { Authorization: `Bearer ${token}` },
        });

        if (!response.ok) {
            throw new Error(`Failed to fetch ${ext.toUpperCase()}: ${response.status}`);
        }

        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const safeTitle = (reportTitle || 'Meeting_Documentation')
            .replace(/[^a-zA-Z0-9-_ ]/g, '_')
            .replace(/\s+/g, '_');
        a.download = `${safeTitle}.${ext}`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);

        showNotification(`${ext.toUpperCase()} downloaded successfully!`, 'success');
    } catch (error) {
        console.error(`[VIDEO ANALYSIS] Error downloading ${ext}:`, error);
        showNotification(`Error: ${error.message}`, 'error');
    } finally {
        if (button) {
            button.disabled = false;
            button.innerHTML = originalHTML;
        }
    }
}

async function downloadSuperAdminVideoAnalysisPDF(historyId, pdfTitle) {
    return downloadSuperAdminVideoAnalysisReport(historyId, pdfTitle, 'pdf');
}

async function deleteSuperAdminVideoAnalysisReport(historyId, pdfTitle) {
    if (!confirm(`Are you sure you want to delete the report "${pdfTitle}"?\n\nThis will permanently delete the exported report from the system and cannot be undone.`)) {
        return;
    }

    const button = event.target.closest('.btn-danger');
    const originalHTML = button ? button.innerHTML : '';
    const reportCard = button ? button.closest('[style*="padding"]') : null;
    const modal = document.querySelector('.modal-overlay');
    const userId = modal ? modal.dataset.userId : null;

    try {
        if (button) {
            button.disabled = true;
            button.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Deleting...';
        }

        const token = window.authToken || localStorage.getItem('authToken');
        // POST, not DELETE (VAPT: HTTP DELETE Method Enabled) — this call bypasses apiCall,
        // so the /delete suffix is spelled out here.
        const response = await fetch(`/video-analysis/delete/${encodeURIComponent(historyId)}/delete`, {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json',
            },
        });

        const data = await response.json();

        if (response.ok && data.success) {
            showNotification('Report deleted successfully! Owner has been notified.', 'success');

            if (reportCard) {
                reportCard.style.opacity = '0';
                reportCard.style.transform = 'scale(0.9)';
                setTimeout(() => {
                    reportCard.remove();

                    if (modal && userId) {
                        const header = modal.querySelector('.modal-header h2');
                        if (header) {
                            const match = header.textContent.match(/Video Analysis Reports - (.+)/);
                            if (match) {
                                const userEmail = match[1];
                                modal.remove();
                                viewVideoAnalysisUserReports(userId, userEmail);
                            }
                        }
                    }

                    // Auto-refresh the main Video Analysis Reports tab
                    console.log('[VIDEO ANALYSIS DELETE] Auto-refreshing main Video Analysis Reports tab');
                    const videoAnalysisTab = document.querySelector('[data-tab="video-analysis-reports"]');
                    if (videoAnalysisTab) {
                        // Show spinner while loading
                        showLoader();
                        
                        // Reload the main tab data
                        loadAllVideoAnalysisReports().then(() => {
                            console.log('[VIDEO ANALYSIS DELETE] Main tab refreshed successfully');
                            hideLoader();
                        }).catch(error => {
                            console.error('[VIDEO ANALYSIS DELETE] Error refreshing main tab:', error);
                            hideLoader();
                        });
                    }
                }, 300);
            }
        } else {
            throw new Error(data.detail || data.message || 'Failed to delete report');
        }
        
    } catch (error) {
        console.error('[VIDEO ANALYSIS] Error deleting report:', error);
        showNotification(`Error: ${error.message}`, 'error');
        
        // Restore button state on error
        if (button) {
            button.disabled = false;
            button.innerHTML = originalHTML;
        }
    }
}

async function viewSuperAdminVideoAnalysisPDF(historyId, pdfTitle) {
    const button = event.target.closest('.btn-primary');
    const originalHTML = button ? button.innerHTML : '';
    
    try {
        // Show processing state
        if (button) {
            button.disabled = true;
            button.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
        }
        
        const token = window.authToken || localStorage.getItem('authToken');
        
        // Fetch PDF to verify it exists
        const response = await fetch(`/video-analysis/view-pdf/${historyId}`, {
            headers: {
                'Authorization': `Bearer ${token}`
            }
        });
        
        if (!response.ok) {
            throw new Error(`Failed to fetch PDF: ${response.status}`);
        }
        
        // Create blob and object URL
        const blob = await response.blob();
        const blobUrl = URL.createObjectURL(blob);
        
        // Open in new window/tab with PDF viewer
        const newWindow = window.open(blobUrl, '_blank');
        if (!newWindow) {
            throw new Error('Failed to open PDF. Please check your popup blocker settings.');
        }
        
        // Restore button state
        if (button) {
            button.disabled = false;
            button.innerHTML = originalHTML;
        }
        
        showNotification('PDF opened in new window', 'success');
        
    } catch (error) {
        console.error('[VIDEO ANALYSIS] Error viewing PDF:', error);
        showNotification(`Error: ${error.message}`, 'error');
        
        // Restore button state on error
        if (button) {
            button.disabled = false;
            button.innerHTML = originalHTML;
        }
    }
}

function copyToClipboard(text) {
    navigator.clipboard.writeText(text).then(() => {
        // Show temporary success message
        const originalText = event.target.innerHTML;
        event.target.innerHTML = '<i class="fas fa-check"></i> Copied!';
        event.target.style.background = '#27ae60';
        setTimeout(() => {
            event.target.innerHTML = originalText;
            event.target.style.background = '';
        }, 2000);
    }).catch(err => {
        console.error('Failed to copy:', err);
        alert('Failed to copy to clipboard');
    });
}

function getVideoAnalysisAuthToken() {
    if (window.authToken) return window.authToken;
    try {
        return localStorage.getItem('authToken');
    } catch (e) {
        return null;
    }
}

function normalizeFrameTimestamp(ts) {
    if (!ts) return ts;
    const parts = String(ts).trim().split(':');
    if (parts.length === 2) {
        return `${parseInt(parts[0], 10).toString().padStart(2, '0')}:${parseInt(parts[1], 10).toString().padStart(2, '0')}`;
    }
    return String(ts).trim();
}

function revealLoadedFrameImage(img, loadingDiv, imgId) {
    if (loadingDiv && loadingDiv.classList.contains('image-loading')) {
        loadingDiv.style.display = 'none';
    }
    img.style.display = 'block';
    img.style.width = '100%';
    img.style.borderRadius = '8px';
    img.style.marginTop = '10px';
    img.style.cursor = 'pointer';
    img.title = 'Click to zoom';
    console.log(`[LOAD FRAME] Image ${imgId} loaded successfully`);
}

function bindFrameZoom(img, blobUrl, sessionId, timestamp) {
    const frameApiPath = `/video-analysis/frame/${encodeURIComponent(sessionId)}/${encodeURIComponent(timestamp)}`;
    img.onclick = () => window.openImageZoom && window.openImageZoom(blobUrl, frameApiPath);
}

function collectFigureTimestampsFromMarkdown(markdown) {
    if (!markdown) return [];
    const pattern = /^###\s*Figure\s+(\d+)\s*\n\*\*Timestamp:\*\*\s*`?(\d{1,2}:\d{2})`?|(?:\*\*Figure\s+(\d+)\*\*\s*\|\s*Timestamp:\s*(\d{1,2}:\d{2}))/gim;
    const timestamps = [];
    let match;
    while ((match = pattern.exec(markdown)) !== null) {
        const ts = normalizeFrameTimestamp(match[2] || match[4]);
        if (ts) timestamps.push(ts);
    }
    return timestamps;
}

function clearVideoFrameCache() {
    cachedFrameUrlsByKey.forEach((url) => {
        if (url) URL.revokeObjectURL(url);
    });
    cachedFrameUrlsByKey.clear();
    inFlightFrameLoads.clear();
}

function frameImageNeedsLoad(img) {
    if (!img?.dataset?.timestamp) return false;
    const loadingDiv = img.closest('.figure-image-preview')?.querySelector('.image-loading');
    if (loadingDiv && window.getComputedStyle(loadingDiv).display !== 'none') {
        return true;
    }
    if (!img.getAttribute('src') || img.style.display === 'none') {
        return true;
    }
    return !(img.complete && img.naturalWidth > 0);
}

function applyFrameBlobToDom(sessionId, timestamp, blobUrl, preferredImgId = null) {
    if (!blobUrl) return 0;
    const normalizedTs = normalizeFrameTimestamp(timestamp);
    const targets = [];
    if (preferredImgId) {
        const preferred = document.getElementById(preferredImgId);
        if (preferred) targets.push(preferred);
    }
    if (targets.length === 0) {
        document.querySelectorAll('img.lazy-frame[data-timestamp]').forEach((img) => {
            if (normalizeFrameTimestamp(img.dataset.timestamp) === normalizedTs) {
                targets.push(img);
            }
        });
    }
    targets.forEach((img) => {
        const previewCard = img.closest('.figure-image-preview');
        const loadingDiv = previewCard
            ? previewCard.querySelector('.image-loading')
            : img.nextElementSibling;
        if (img.src === blobUrl && img.complete && img.naturalWidth > 0) {
            revealLoadedFrameImage(img, loadingDiv, img.id);
            return;
        }
        img.onload = () => revealLoadedFrameImage(img, loadingDiv, img.id);
        img.onerror = () => {
            console.error(`[LOAD FRAME] Image ${img.id} failed to render`);
        };
        img.src = blobUrl;
        bindFrameZoom(img, blobUrl, sessionId, normalizedTs);
        if (img.complete && img.naturalWidth > 0) {
            revealLoadedFrameImage(img, loadingDiv, img.id);
        }
    });
    return targets.length;
}

function applyAllCachedFramesToPreview() {
    const sessionId = videoAnalysisSession.sessionId;
    if (!sessionId) return;
    document.querySelectorAll('img.lazy-frame[data-timestamp]').forEach((img) => {
        const normalizedTs = normalizeFrameTimestamp(img.dataset.timestamp);
        const cachedUrl = cachedFrameUrlsByKey.get(`${sessionId}|${normalizedTs}`);
        if (cachedUrl) {
            applyFrameBlobToDom(sessionId, normalizedTs, cachedUrl, img.id);
        }
    });
}

async function fetchFrameBlobUrl(sessionId, timestamp, onReady = null) {
    const normalizedTs = normalizeFrameTimestamp(timestamp);
    if (!sessionId || !normalizedTs) return null;

    const cacheKey = `${sessionId}|${normalizedTs}`;
    const cachedUrl = cachedFrameUrlsByKey.get(cacheKey);
    if (cachedUrl) {
        if (typeof onReady === 'function') onReady(cachedUrl);
        return cachedUrl;
    }

    let fetchPromise = inFlightFrameLoads.get(cacheKey);
    if (!fetchPromise) {
        const token = getVideoAnalysisAuthToken();
        if (!token) return null;

        fetchPromise = (async () => {
            const token = getVideoAnalysisAuthToken();
            if (!token) return null;

            const url = `/video-analysis/frame/${encodeURIComponent(sessionId)}/${encodeURIComponent(normalizedTs)}`;
            for (let attempt = 0; attempt < 3; attempt++) {
                try {
                    const response = await fetch(url, {
                        headers: { 'Authorization': `Bearer ${token}` }
                    });
                    console.log(`[LOAD FRAME] Response for ${normalizedTs} (attempt ${attempt + 1}): ${response.status}`);
                    if (response.ok) {
                        const blob = await response.blob();
                        if (blob && blob.size > 0) {
                            return URL.createObjectURL(blob);
                        }
                    }
                    if (response.status !== 404 || attempt >= 2) {
                        return null;
                    }
                    await new Promise((resolve) => setTimeout(resolve, 250 * (attempt + 1)));
                } catch (err) {
                    console.error(`[LOAD FRAME] Error loading frame ${normalizedTs}:`, err);
                    if (attempt >= 2) return null;
                    await new Promise((resolve) => setTimeout(resolve, 250 * (attempt + 1)));
                }
            }
            return null;
        })().finally(() => {
            inFlightFrameLoads.delete(cacheKey);
        });
        inFlightFrameLoads.set(cacheKey, fetchPromise);
    }

    const blobUrl = await fetchPromise;
    if (blobUrl) {
        cachedFrameUrlsByKey.set(cacheKey, blobUrl);
        if (typeof onReady === 'function') onReady(blobUrl);
    }
    return blobUrl;
}

async function warmVideoFrameCache(sessionId, markdown) {
    const timestamps = collectFigureTimestampsFromMarkdown(markdown);
    if (!sessionId || timestamps.length === 0) return;

    videoFrameWarmInProgress = true;
    console.log(`[FRAME CACHE] Warming ${timestamps.length} frames`);
    let nextIndex = 0;
    let activeCount = 0;

    try {
        await new Promise((resolve) => {
            const pump = () => {
                while (activeCount < VA_FRAME_LOAD_CONCURRENCY && nextIndex < timestamps.length) {
                    const ts = timestamps[nextIndex++];
                    activeCount++;
                    fetchFrameBlobUrl(sessionId, ts, () => {
                        applyAllCachedFramesToPreview();
                    }).finally(() => {
                        activeCount--;
                        if (nextIndex >= timestamps.length && activeCount === 0) {
                            resolve();
                        } else {
                            pump();
                        }
                    });
                }
                if (timestamps.length === 0) resolve();
            };
            pump();
        });
    } finally {
        videoFrameWarmInProgress = false;
    }
}

// Helper function to load frame images with authentication
async function loadFrameImage(imgId, sessionId, timestamp) {
    const normalizedTs = normalizeFrameTimestamp(timestamp);
    const cacheKey = `${sessionId}|${normalizedTs}`;
    console.log(`[LOAD FRAME] Starting load for ${imgId} at ${normalizedTs}`);

    try {
        const blobUrl = await fetchFrameBlobUrl(sessionId, normalizedTs);
        if (!blobUrl) {
            const img = document.getElementById(imgId);
            const previewCard = img ? img.closest('.figure-image-preview') : null;
            const loadingDiv = previewCard
                ? previewCard.querySelector('.image-loading')
                : (img ? img.nextElementSibling : null);
            if (loadingDiv && loadingDiv.classList.contains('image-loading')) {
                loadingDiv.innerHTML = '<i class="fas fa-exclamation-triangle"></i> Failed to load frame';
                loadingDiv.style.color = '#dc3545';
            }
            return;
        }

        applyFrameBlobToDom(sessionId, normalizedTs, blobUrl, imgId);
    } catch (error) {
        console.error(`[LOAD FRAME] Error loading frame ${normalizedTs}:`, error);
        const img = document.getElementById(imgId);
        const previewCard = img ? img.closest('.figure-image-preview') : null;
        const loadingDiv = previewCard
            ? previewCard.querySelector('.image-loading')
            : (img ? img.nextElementSibling : null);
        if (loadingDiv && loadingDiv.classList.contains('image-loading')) {
            loadingDiv.innerHTML = '<i class="fas fa-exclamation-triangle"></i> Failed to load frame';
            loadingDiv.style.color = '#dc3545';
        }
    }
}

function enhanceVideoFiguresInPreview(preview) {
    if (!preview) return;

    const sessionId = videoAnalysisSession.sessionId;
    const sources = Array.from(preview.querySelectorAll('.md-sync-source'));
    let figureCounter = 0;

    const injectFigurePreview = (anchorEl, figNum, timestamp) => {
        if (!anchorEl) return;
        if (anchorEl.nextElementSibling?.classList?.contains('figure-marker')) return;
        figureCounter += 1;
        const imgId = `frame-img-${figureCounter}`;
        const normalizedTs = normalizeFrameTimestamp(timestamp);
        const cachedUrl = sessionId ? cachedFrameUrlsByKey.get(`${sessionId}|${normalizedTs}`) : null;
        const imgStyle = cachedUrl ? 'display:block;' : 'display:none;';
        const loadingStyle = cachedUrl ? 'display:none;' : '';

        const wrapper = document.createElement('div');
        wrapper.className = 'figure-marker';
        wrapper.innerHTML =
            '<div class="figure-header">' +
            '<span class="figure-number"><i class="fas fa-image"></i> Fig. ' + figNum + '</span>' +
            '<span class="figure-timestamp"><i class="fas fa-clock"></i> ' + timestamp + '</span>' +
            '</div>' +
            (sessionId
                ? '<div class="figure-image-preview">' +
                  '<img id="' + imgId + '" data-timestamp="' + timestamp + '" alt="Frame at ' + timestamp + '" style="' + imgStyle + '" class="lazy-frame"' + (cachedUrl ? ' src="' + cachedUrl + '"' : '') + ' />' +
                  '<div class="image-loading" style="' + loadingStyle + '"><i class="fas fa-spinner fa-spin"></i> Loading frame...</div>' +
                  '</div>'
                : '');

        anchorEl.insertAdjacentElement('afterend', wrapper);
    };

    sources.forEach((block, index) => {
        const blockText = (block.textContent || '').replace(/\s+/g, ' ').trim();
        const h3 = block.querySelector('h3');
        const h3Match = h3 ? h3.textContent.trim().match(/^Figure\s+(\d+)/i) : null;
        const inlineMatch = blockText.match(/Figure\s+(\d+).*?(\d{1,2}:\d{2})/i);
        const legacyMatch = blockText.match(/Figure\s+(\d+).*?Timestamp:\s*(\d{1,2}:\d{2})/i);
        const imageTagMatch = blockText.match(/\[IMAGE:\s*(\d{1,2}:\d{2}(?::\d{2})?)\s*\]/i);

        if (h3Match) {
            let timestamp = null;
            const nextText = (sources[index + 1]?.textContent || '').trim();
            const nextTs = nextText.match(/(\d{1,2}:\d{2})/);
            if (nextTs) timestamp = nextTs[1];
            if (!timestamp) {
                const sameTs = blockText.match(/(\d{1,2}:\d{2})/);
                if (sameTs) timestamp = sameTs[1];
            }
            if (timestamp) {
                injectFigurePreview(h3 || block, h3Match[1], timestamp);
            }
            return;
        }

        if (imageTagMatch) {
            injectFigurePreview(block, String(figureCounter + 1), imageTagMatch[1]);
            return;
        }

        if (inlineMatch) {
            injectFigurePreview(block, inlineMatch[1], inlineMatch[2]);
            return;
        }

        if (legacyMatch) {
            injectFigurePreview(block, legacyMatch[1], legacyMatch[2]);
        }
    });
}

function updateMarkdownPreview(options = {}) {
    // Skip preview updates during save operations
    if (isSavingMarkdown) {
        console.log('[MARKDOWN PREVIEW] Skipping update during save');
        return;
    }
    
    const editor = document.getElementById('video-markdown-editor');
    const preview = document.getElementById('video-markdown-preview');
    
    if (!editor || !preview) return;
    
    const markdown = editor.value;
    
    // Update stats
    const wordCount = markdown.split(/\s+/).filter(w => w.length > 0).length;
    const imageCount = (markdown.match(/\[IMAGE:/g) || []).length +
        (markdown.match(/\*\*Figure \d+\*\*/g) || []).length +
        (markdown.match(/^###\s+Figure\s+\d+/gim) || []).length;
    
    document.getElementById('markdown-word-count').textContent = wordCount.toLocaleString();
    document.getElementById('markdown-image-count').textContent = imageCount;
    
    if (typeof window.renderMarkdownWithImages === 'function') {
        preview.innerHTML = window.renderMarkdownWithImages(markdown, preview);
    } else {
        preview.textContent = markdown;
    }

    enhanceVideoFiguresInPreview(preview);

    applyAllCachedFramesToPreview();
    if (!options.skipFrameFetch) {
        setupLazyFrameLoading();
    }
}

// Track loaded frames and cache by session/timestamp for snappier previews.
const cachedFrameUrlsByKey = new Map(); // key: `${sessionId}|${timestamp}`
const inFlightFrameLoads = new Map();   // key: `${sessionId}|${timestamp}` -> Promise
let frameLazyObserver = null;
let isSavingMarkdown = false;
let videoFrameWarmInProgress = false;

function loadAllFrameImagesInParallel(imagesToLoad) {
    const sessionId = videoAnalysisSession.sessionId;
    if (!sessionId || imagesToLoad.length === 0) return;

    const queue = imagesToLoad
        .map((img) => ({
            imgId: img.id,
            timestamp: normalizeFrameTimestamp(img.dataset.timestamp),
        }))
        .filter((item) => item.imgId && item.timestamp);

    if (queue.length === 0) return;

    console.log(`[FRAME LOAD] Retrying ${queue.length} pending frames (concurrency ${VA_FRAME_LOAD_CONCURRENCY})`);

    let nextIndex = 0;
    let activeCount = 0;

    const pump = () => {
        while (activeCount < VA_FRAME_LOAD_CONCURRENCY && nextIndex < queue.length) {
            const item = queue[nextIndex++];
            const cacheKey = `${sessionId}|${item.timestamp}`;
            if (cachedFrameUrlsByKey.has(cacheKey)) {
                applyFrameBlobToDom(sessionId, item.timestamp, cachedFrameUrlsByKey.get(cacheKey), item.imgId);
                pump();
                continue;
            }
            if (inFlightFrameLoads.has(cacheKey)) {
                inFlightFrameLoads.get(cacheKey).then((blobUrl) => {
                    if (blobUrl) applyFrameBlobToDom(sessionId, item.timestamp, blobUrl, item.imgId);
                }).finally(() => pump());
                continue;
            }
            activeCount++;
            loadFrameImage(item.imgId, sessionId, item.timestamp).finally(() => {
                activeCount--;
                pump();
            });
        }
    };

    pump();
}

// Apply cached blobs and retry any figures still showing a spinner.
function setupLazyFrameLoading() {
    requestAnimationFrame(() => {
        if (frameLazyObserver) {
            frameLazyObserver.disconnect();
            frameLazyObserver = null;
        }

        applyAllCachedFramesToPreview();

        if (videoFrameWarmInProgress) {
            return;
        }

        const imagesToLoad = Array.from(document.querySelectorAll('img.lazy-frame[data-timestamp]'))
            .filter((img) => frameImageNeedsLoad(img));

        if (imagesToLoad.length === 0) {
            return;
        }

        loadAllFrameImagesInParallel(imagesToLoad);
    });
}

async function saveMarkdown() {
    console.log('[VIDEO ANALYSIS] Saving markdown...');
    
    // Cancel any pending preview updates immediately
    if (window.previewUpdateTimeout) {
        clearTimeout(window.previewUpdateTimeout);
        window.previewUpdateTimeout = null;
        console.log('[VIDEO ANALYSIS] Cancelled pending preview update');
    }
    
    const editor = document.getElementById('video-markdown-editor');
    if (!editor || !videoAnalysisSession.sessionId) {
        console.log('[VIDEO ANALYSIS] Save aborted - no editor or session');
        return;
    }
    
    const saveBtn = document.getElementById('save-markdown-btn');
    if (!saveBtn) {
        console.log('[VIDEO ANALYSIS] Save aborted - no save button');
        return;
    }
    
    // Check if already saving
    if (isSavingMarkdown) {
        console.log('[VIDEO ANALYSIS] Already saving, ignoring duplicate request');
        return;
    }
    
    // Set saving flag to prevent preview updates during save
    isSavingMarkdown = true;
    
    const originalText = saveBtn.innerHTML;
    saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
    saveBtn.disabled = true;
    
    try {
        console.log('[VIDEO ANALYSIS] Preparing markdown data...');
        const formData = new FormData();
        formData.append('markdown', editor.value);
        
        console.log('[VIDEO ANALYSIS] Sending save request...');
        const response = await apiCall(
            `/video-analysis/update-markdown/${encodeURIComponent(videoAnalysisSession.sessionId)}`,
            'POST',
            formData,
            true // isFormData
        );
        
        console.log('[VIDEO ANALYSIS] Save response received:', response);
        
        // apiCall returns {success: true, data: {...}} format
        if (response && response.success) {
            showNotification('Saved successfully!', 'success');
            
            // Update last saved time
            const lastSavedEl = document.getElementById('last-saved-time');
            if (lastSavedEl) {
                lastSavedEl.textContent = 'Just now';
                lastSavedEl.style.color = ''; // Reset to default color
            }
            
            // Immediately hide save button and show export buttons
            saveBtn.style.display = 'none';
            setVideoExportButtonsVisible(true);
        } else {
            throw new Error('Save failed');
        }
        
    } catch (error) {
        console.error('[VIDEO ANALYSIS] Save error:', error);
        showNotification(`Error saving`, 'error');
        saveBtn.innerHTML = originalText;
        saveBtn.disabled = false;
    } finally {
        // Clear saving flag
        isSavingMarkdown = false;
    }
}

function setVideoExportButtonsVisible(visible) {
    const pdfBtn = document.getElementById('generate-pdf-btn');
    const docxBtn = document.getElementById('generate-docx-btn');
    const display = visible ? 'inline-block' : 'none';
    [pdfBtn, docxBtn].forEach((btn) => {
        if (btn) {
            btn.style.display = display;
            btn.disabled = !visible;
        }
    });
}

const VA_EXPORT_PIPELINES = {
    pdf: {
        title: 'Generating PDF report',
        steps: [
            { label: 'Saving your latest edits', icon: 'fa-save' },
            { label: 'Rendering PDF layout and embedding screenshots', icon: 'fa-file-pdf' },
            { label: 'Uploading document to secure storage', icon: 'fa-cloud-upload-alt' },
            { label: 'Archiving source video for future re-index', icon: 'fa-video' },
            { label: 'Indexing report for Chat with Reports (search + frames)', icon: 'fa-database' },
            { label: 'Preparing your download', icon: 'fa-download' },
        ],
    },
    docx: {
        title: 'Generating Word document',
        steps: [
            { label: 'Saving your latest edits', icon: 'fa-save' },
            { label: 'Building editable Word document with figures', icon: 'fa-file-word' },
            { label: 'Uploading document to secure storage', icon: 'fa-cloud-upload-alt' },
            { label: 'Archiving source video for future re-index', icon: 'fa-video' },
            { label: 'Indexing report for Chat with Reports (search + frames)', icon: 'fa-database' },
            { label: 'Preparing your download', icon: 'fa-download' },
        ],
    },
};

let vaExportSimTimer = null;

function beginVaExportProgress(format) {
    const key = format === 'docx' ? 'docx' : 'pdf';
    const pipeline = VA_EXPORT_PIPELINES[key];
    const panel = document.getElementById('va-export-progress-panel');
    const titleEl = document.getElementById('va-export-progress-title');
    const statusEl = document.getElementById('va-export-progress-status');
    const barEl = document.getElementById('va-export-progress-bar');
    const stepsEl = document.getElementById('va-export-progress-steps');
    let currentStep = 0;

    const renderSteps = () => {
        if (!stepsEl) return;
        stepsEl.innerHTML = pipeline.steps
            .map((step, i) => {
                let state = 'pending';
                if (i < currentStep) state = 'done';
                else if (i === currentStep) state = 'active';
                let iconClass = step.icon;
                if (state === 'done') iconClass = 'fa-check-circle';
                else if (state === 'active') iconClass = 'fa-circle-notch fa-spin';
                return (
                    `<li class="va-export-step va-export-step-${state}">` +
                    `<i class="fas ${iconClass} va-export-step-icon" aria-hidden="true"></i>` +
                    `<span>${step.label}</span></li>`
                );
            })
            .join('');
    };

    const setProgress = (stepIndex, statusText) => {
        currentStep = Math.min(stepIndex, pipeline.steps.length - 1);
        const pct = Math.round(((currentStep + 1) / pipeline.steps.length) * 100);
        if (barEl) barEl.style.width = `${pct}%`;
        if (statusEl) {
            statusEl.textContent = statusText || pipeline.steps[currentStep]?.label || '';
        }
        renderSteps();
    };

    if (panel) {
        panel.classList.remove('hidden');
        panel.setAttribute('aria-busy', 'true');
        panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
    const editStep = document.getElementById('video-edit-step');
    if (editStep) editStep.classList.add('va-export-in-progress');
    if (titleEl) titleEl.textContent = pipeline.title;
    setProgress(0);

    if (vaExportSimTimer) clearInterval(vaExportSimTimer);
    let simStep = 1;
    vaExportSimTimer = setInterval(() => {
        if (simStep < 4 && simStep > currentStep) {
            setProgress(simStep);
        }
        simStep += 1;
        if (simStep > 4) {
            clearInterval(vaExportSimTimer);
            vaExportSimTimer = null;
        }
    }, 4500);

    return {
        setProgress,
        finishIndex(meta) {
            if (vaExportSimTimer) {
                clearInterval(vaExportSimTimer);
                vaExportSimTimer = null;
            }
            const frames = meta?.frames || '0';
            const chunks = meta?.chunks || '0';
            const status = meta?.status || 'indexed';
            if (status === 'indexed') {
                setProgress(
                    4,
                    `Indexed for chat: ${frames} screenshot(s), ${chunks} search section(s)`
                );
                showNotification(
                    `Report indexed for Chat with Reports (${frames} frames).`,
                    'success'
                );
            } else {
                setProgress(
                    4,
                    meta?.warning
                        ? `Indexing issue: ${meta.warning}`
                        : 'Indexing skipped or failed — you can Reindex from View All Reports'
                );
                showNotification(
                    'Document saved, but chat indexing had an issue. Use Reindex in View All Reports.',
                    'warning'
                );
            }
        },
        complete(label) {
            if (vaExportSimTimer) {
                clearInterval(vaExportSimTimer);
                vaExportSimTimer = null;
            }
            setProgress(pipeline.steps.length - 1, `Download starting — ${label} ready`);
            if (barEl) barEl.style.width = '100%';
        },
        hide() {
            if (vaExportSimTimer) {
                clearInterval(vaExportSimTimer);
                vaExportSimTimer = null;
            }
            if (panel) {
                panel.classList.add('hidden');
                panel.setAttribute('aria-busy', 'false');
            }
            const editStep = document.getElementById('video-edit-step');
            if (editStep) editStep.classList.remove('va-export-in-progress');
            if (barEl) barEl.style.width = '0%';
        },
    };
}

/** Resolve a length-safe PDF/DOCX download name with fallbacks. */
function resolveVideoAnalysisExportFilename(contentDisposition, exportFormat) {
    const ext = exportFormat === 'docx' ? 'docx' : 'pdf';
    const fallback = `Meeting_Documentation.${ext}`;
    const maxLen = 100;

    let candidate = '';
    const header = String(contentDisposition || '');
    const starred = header.match(/filename\*\s*=\s*UTF-8''([^;]+)/i);
    const plain = header.match(/filename\s*=\s*("?)([^";]+)\1/i);
    if (starred && starred[1]) {
        try {
            candidate = decodeURIComponent(starred[1].trim());
        } catch {
            candidate = starred[1].trim();
        }
    } else if (plain && plain[2]) {
        candidate = plain[2].trim().replace(/^["']|["']$/g, '');
    }

    candidate = String(candidate || '')
        .replace(/^.*[\\/]/, '')
        .replace(/[<>:"|?*\x00-\x1f]/g, '_')
        .replace(/\s+/g, '_')
        .replace(/_+/g, '_')
        .trim();

    if (!candidate) candidate = fallback;
    if (!candidate.toLowerCase().endsWith(`.${ext}`)) {
        const stem = candidate.replace(/\.[^.]+$/, '') || 'Meeting_Documentation';
        candidate = `${stem}.${ext}`;
    }

    if (candidate.length > maxLen) {
        const suffix = `.${ext}`;
        const keep = Math.max(8, maxLen - suffix.length);
        candidate = `${candidate.slice(0, keep).replace(/[._-]+$/g, '')}${suffix}`;
    }

    if (!candidate || candidate.length > maxLen || candidate === `.${ext}`) {
        const stamp = new Date()
            .toISOString()
            .replace(/[-:TZ.]/g, '')
            .slice(0, 14);
        return `VA_Report_${stamp}.${ext}`;
    }
    return candidate;
}

async function generateVideoReport(exportFormat) {
    const format = (exportFormat || 'pdf').toLowerCase();
    const isDocx = format === 'docx';
    const label = isDocx ? 'DOCX' : 'PDF';
    console.log(`[VIDEO ANALYSIS] Generating ${label}...`);

    const editor = document.getElementById('video-markdown-editor');
    if (!editor) return;

    const activeBtn = document.getElementById(isDocx ? 'generate-docx-btn' : 'generate-pdf-btn');
    const otherBtn = document.getElementById(isDocx ? 'generate-pdf-btn' : 'generate-docx-btn');
    if (!activeBtn) return;

    const originalText = activeBtn.innerHTML;
    activeBtn.innerHTML =
        `<span class="va-inline-spinner" aria-hidden="true"></span> Generating ${label}...`;
    activeBtn.setAttribute('aria-busy', 'true');
    activeBtn.disabled = true;
    if (otherBtn) otherBtn.disabled = true;

    videoAnalysisSession.isExportInFlight = true;
    const progress = beginVaExportProgress(format);
    const saveBtn = document.getElementById('save-markdown-btn');
    if (saveBtn) saveBtn.disabled = true;
    const startOverBtn = document.getElementById('start-over-btn');
    if (startOverBtn) startOverBtn.disabled = true;

    let indexMeta = null;

    try {
        progress.setProgress(0);
        const formData = new FormData();
        formData.append('markdown', editor.value);
        await apiCall(
            `/video-analysis/update-markdown/${encodeURIComponent(videoAnalysisSession.sessionId)}`,
            'POST',
            formData,
            true
        );

        progress.setProgress(1, 'Rendering document with embedded meeting screenshots…');

        const token = window.authToken || localStorage.getItem('authToken');
        const response = await fetch(
            `/video-analysis/generate-report/${videoAnalysisSession.sessionId}?format=${format}`,
            {
                method: 'POST',
                headers: { Authorization: `Bearer ${token}` },
            }
        );

        if (!response.ok) {
            const errBody = await response.json().catch(() => ({}));
            throw new Error(errBody.detail || `Failed to generate ${label}`);
        }

        indexMeta = {
            status: response.headers.get('X-VA-Index-Status') || 'unknown',
            frames: response.headers.get('X-VA-Frames-Embedded') || '0',
            chunks: response.headers.get('X-VA-Chunk-Count') || '0',
            warning: response.headers.get('X-VA-Index-Warning') || '',
        };
        progress.finishIndex(indexMeta);
        progress.setProgress(5, 'Your file is ready — starting download…');

        const contentDisposition = response.headers.get('Content-Disposition');
        let filename = resolveVideoAnalysisExportFilename(
            contentDisposition,
            isDocx ? 'docx' : 'pdf'
        );

        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);

        progress.complete(filename);
        const indexNote =
            indexMeta.status === 'indexed'
                ? ` Indexed for Chat with Reports (${indexMeta.frames} frames).`
                : '';
        showNotification(`${label} downloaded successfully!${indexNote}`, 'success');
        showExportSuccessModal(format, indexMeta);

        setTimeout(() => {
            returnToVideoAnalysisMainScreen({ clearSession: true, notify: false });
            const reportsModal = document.getElementById('all-reports-modal');
            if (reportsModal && !reportsModal.classList.contains('hidden')) {
                loadVideoAnalysisHistory();
            }
        }, 1200);
    } catch (error) {
        console.error(`[VIDEO ANALYSIS] ${label} generation error:`, error);
        showNotification(`Error generating ${label}: ${error.message}`, 'error');
    } finally {
        videoAnalysisSession.isExportInFlight = false;
        setTimeout(() => progress.hide(), indexMeta ? 4000 : 1500);
        activeBtn.innerHTML = originalText;
        activeBtn.removeAttribute('aria-busy');
        activeBtn.disabled = false;
        if (otherBtn) otherBtn.disabled = false;
        if (saveBtn) saveBtn.disabled = false;
        if (startOverBtn) startOverBtn.disabled = false;
    }
}

/** @deprecated Use generateVideoReport('pdf') */
async function generateVideoPDF() {
    return generateVideoReport('pdf');
}

function returnToVideoAnalysisMainScreen(options = {}) {
    const { clearSession = false, notify = false } = options;

    const playerContainer = document.getElementById('video-player-container');
    const toggleBtn = document.getElementById('toggle-video-player-btn');
    if (playerContainer) playerContainer.style.display = 'none';
    if (toggleBtn) {
        toggleBtn.innerHTML = '<i class="fas fa-play-circle"></i> View Recording';
    }

    const exportPanel = document.getElementById('va-export-progress-panel');
    if (exportPanel) {
        exportPanel.classList.add('hidden');
        exportPanel.setAttribute('aria-busy', 'false');
    }
    document.getElementById('video-edit-step')?.classList.remove('va-export-in-progress');

    // Revoke any object URL used by the meeting player
    const meetingVideo = document.getElementById('meeting-video-player');
    if (meetingVideo?.src) {
        try {
            URL.revokeObjectURL(meetingVideo.src);
        } catch { /* ignore */ }
        meetingVideo.removeAttribute('src');
        meetingVideo.load?.();
    }

    if (clearSession && videoAnalysisSession.sessionId) {
        apiCall(
            `/video-analysis/session/${encodeURIComponent(videoAnalysisSession.sessionId)}`,
            'DELETE',
            null,
            false,
            1,
            true
        ).catch(() => {});
    }

    stopVideoStatusPolling();
    clearVideoFrameCache();

    const keptEnhanced = videoAnalysisSession.enhancedSequenceAnalysis;
    videoAnalysisSession = {
        sessionId: null,
        videoFile: null,
        transcriptFile: null,
        originalVideoFile: null,
        enhancedSequenceAnalysis: keptEnhanced,
        processingInterval: null,
        statusPollInFlight: false,
        lastKnownProgress: 0,
        uploadXhr: null,
        uploadCompleted: false,
        cancelRequested: false,
        userCancelledAnalysis: false,
        isProcessingActive: false,
        isExportInFlight: false,
    };

    const editor = document.getElementById('video-markdown-editor');
    if (editor) editor.value = '';

    // Clear previous video/transcript selections from the upload UI
    const videoInput = document.getElementById('video-file-input');
    const transcriptInput = document.getElementById('transcript-file-input');
    if (videoInput) videoInput.value = '';
    if (transcriptInput) transcriptInput.value = '';
    const videoName = document.getElementById('video-file-name');
    const transcriptName = document.getElementById('transcript-file-name');
    if (videoName) videoName.textContent = '';
    if (transcriptName) transcriptName.textContent = '';
    const customInstructions = document.getElementById('video-custom-instructions');
    if (customInstructions) customInstructions.value = '';

    resetProcessingSteps();
    updateVideoProgress(0, 'Initializing...');
    showVideoStep('upload');
    checkFilesReady();

    if (typeof switchVideoAnalysisModuleTab === 'function') {
        switchVideoAnalysisModuleTab('analyze');
    }

    if (notify) {
        showNotification('Returned to New Analysis.', 'info');
    }
}

window.returnToVideoAnalysisMainScreen = returnToVideoAnalysisMainScreen;

function cancelVideoEditReturnToUpload() {
    returnToVideoAnalysisMainScreen({ clearSession: true, notify: true });
}

function startOverVideoAnalysis() {
    if (confirm('Are you sure you want to start over? All current progress will be lost.')) {
        // Clean up session
        if (videoAnalysisSession.sessionId) {
            apiCall(`/video-analysis/session/${encodeURIComponent(videoAnalysisSession.sessionId)}`, 'DELETE')
                .catch(err => console.error('Error deleting session:', err));
        }
        
        // Reset state
        stopVideoStatusPolling();
        clearVideoFrameCache();
        videoAnalysisSession = {
            sessionId: null,
            videoFile: null,
            transcriptFile: null,
            enhancedSequenceAnalysis: !!document.getElementById('enhanced-analysis-toggle')?.checked,
            processingInterval: null,
            statusPollInFlight: false,
            lastKnownProgress: 0,
            uploadXhr: null,
            uploadCompleted: false,
            cancelRequested: false,
            userCancelledAnalysis: false,
            isProcessingActive: false,
            isExportInFlight: false,
        };
        
        // Clear file inputs
        document.getElementById('video-file-input').value = '';
        document.getElementById('transcript-file-input').value = '';
        document.getElementById('video-file-name').textContent = '';
        document.getElementById('transcript-file-name').textContent = '';
        
        // Reset editor
        const editor = document.getElementById('video-markdown-editor');
        if (editor) {
            editor.value = '';
        }
        
        // Reset processing steps
        resetProcessingSteps();
        
        // Show upload step
        showVideoStep('upload');
        checkFilesReady();
        
        showNotification('Ready to start a new analysis', 'info');
    }
}

function toggleVideoPlayer() {
    const container = document.getElementById('video-player-container');
    const btn = document.getElementById('toggle-video-player-btn');
    
    if (container.style.display === 'none') {
        container.style.display = 'block';
        btn.innerHTML = '<i class="fas fa-eye-slash"></i> Hide Recording';
        
        // Load video if not already loaded
        const video = document.getElementById('meeting-video-player');
        if (video && !video.src && videoAnalysisSession.videoFile) {
            const url = URL.createObjectURL(videoAnalysisSession.videoFile);
            video.src = url;
        }
    } else {
        container.style.display = 'none';
        btn.innerHTML = '<i class="fas fa-play-circle"></i> View Recording';
    }
}

// Extract frame at specific timestamp when user adds it manually
async function extractFrameAtTimestamp(timestamp) {
    if (!videoAnalysisSession.sessionId) {
        showNotification('No active session. Please start a new analysis.', 'error');
        return;
    }
    
    showNotification(`Extracting frame at ${timestamp}...`, 'info');
    
    try {
        const formData = new FormData();
        formData.append('timestamp', timestamp);
        
        const response = await apiCall(
            `/video-analysis/extract-manual-frame/${videoAnalysisSession.sessionId}`,
            'POST',
            formData,
            true
        );
        
        if (response.success) {
            showNotification(`Frame extracted at ${timestamp}!`, 'success');
            
            // Update markdown with description
            const editor = document.getElementById('video-markdown-editor');
            if (editor) {
                const markdown = editor.value;
                const imageTag = `[IMAGE: ${timestamp}]`;
                
                // Count existing figures to get next figure number
                const figureCount = (markdown.match(/\*\*Figure \d+\*\*/g) || []).length;
                const nextFigureNum = figureCount + 1;
                
                const replacement = `**Figure ${nextFigureNum}** | Timestamp: ${timestamp}\n\n${response.description}\n\n---`;
                
                editor.value = markdown.replace(imageTag, replacement);
                updateMarkdownPreview();
            }
        }
        
    } catch (error) {
        console.error('[VIDEO ANALYSIS] Frame extraction error:', error);
        showNotification(`Error extracting frame: ${error.message}`, 'error');
    }
}

