let isLoadingHistory = false;

function renderReportChatIndexStatus(item, options = {}) {
    const { adminMode = false } = options;
    const status = String(item.embedding_status || '').toLowerCase();
    const isIndexed = Boolean(item.has_embeddings) || status === 'indexed';
    const reportId = item.id;

    const indexBtn = (reindex, label) => {
        const btnLabel = label || (reindex ? 'Retry index' : 'Index for Chat');
        if (adminMode) {
            const flag = reindex ? ' data-reindex="1"' : '';
            return (
                `<button type="button" class="btn-report-action btn-index-chat" data-va-admin-index data-history-id="${reportId}"${flag} ` +
                `title="Index this report for Chat with Reports (trainer will be notified)">` +
                `<i class="fas fa-database"></i> ${btnLabel}</button>`
            );
        }
        if (reindex) {
            return (
                `<button type="button" class="btn-report-action btn-reindex" onclick="indexVideoReportForChat('${reportId}', true)" title="Rebuild chat search sections and figure images for this report">` +
                `<i class="fas fa-sync-alt"></i> ${btnLabel}</button>`
            );
        }
        return (
            `<button type="button" class="btn-report-action btn-index-chat" onclick="indexVideoReportForChat('${reportId}')" title="Make this report searchable in Chat with Reports">` +
            `<i class="fas fa-database"></i> Index for Chat</button>`
        );
    };

    if (isIndexed) {
        const chunkHint =
            item.chunk_count != null && item.chunk_count > 0
                ? ` · ${item.chunk_count} search section(s)`
                : '';
        const fmt = (item.export_format || 'pdf').toUpperCase();
        let html =
            `<span class="report-embed-status indexed" title="This ${fmt} report is searchable in Chat with Reports">` +
            `<i class="fas fa-check-circle"></i> Already indexed for chat${chunkHint}</span>`;
        // Reindex is offered to the report owner as well, not just to a super admin: it is what
        // refreshes the figure images after the report's frames become available.
        html += indexBtn(true, 'Reindex');
        return html;
    }
    if (status === 'indexing') {
        return (
            `<span class="report-embed-status indexing">` +
            `<i class="fas fa-spinner fa-spin"></i> Indexing for chat…</span>`
        );
    }
    if (status === 'failed') {
        return (
            `<span class="report-embed-status failed"><i class="fas fa-exclamation-circle"></i> Index failed</span>` +
            indexBtn(true)
        );
    }
    return indexBtn(false);
}

async function loadVideoAnalysisHistory() {
    // Prevent duplicate loading
    if (isLoadingHistory) {
        console.log('[VIDEO HISTORY] Already loading, skipping...');
        return;
    }
    
    isLoadingHistory = true;
    console.log('[VIDEO HISTORY] Loading history...');
    
    try {
        const token = window.authToken || localStorage.getItem('authToken');
        console.log('[VIDEO HISTORY] Using token:', token ? 'Present' : 'Missing');
        
        const response = await fetch('/video-analysis/history', {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json'
            }
        });
        
        console.log('[VIDEO HISTORY] Response status:', response.status);
        
        if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }
        
        const data = await response.json();
        console.log('[VIDEO HISTORY] Raw response:', data);
        
        const loading = document.getElementById('reports-loading');
        const historyList = document.getElementById('video-history-list');
        const empty = document.getElementById('reports-empty');
        
        if (!historyList) {
            console.error('[VIDEO HISTORY] History list element not found');
            return;
        }
        
        // Hide loading
        if (loading) loading.style.display = 'none';
        
        // Check if we have data
        const hasData = data && data.success && data.data && Array.isArray(data.data) && data.data.length > 0;
        console.log('[VIDEO HISTORY] Has data:', hasData, 'Count:', data?.data?.length || 0);
        
        if (hasData) {
            console.log(`[VIDEO HISTORY] Found ${data.data.length} reports`);
            
            historyList.style.display = 'grid';
            if (empty) empty.style.display = 'none';
            
            historyList.innerHTML = data.data.map((item, index) => {
                console.log(`[VIDEO HISTORY] Report ${index}:`, item);
                const exportFmt = (item.export_format || (item.has_docx ? 'docx' : 'pdf')).toLowerCase();
                const isDocx = exportFmt === 'docx' || (item.has_docx && !item.has_pdf);
                const hasReport = item.has_report || item.has_pdf || item.has_docx;
                const fileIcon = isDocx ? 'fa-file-word' : 'fa-file-pdf';
                const formatLabel = isDocx ? 'DOCX' : 'PDF';
                const displayTitle = vaEscapeHtml(item.pdf_title || 'Meeting Documentation');
                const videoName = vaEscapeHtml(
                    vaDisplayVideoFilename(item.video_filename, item.pdf_title)
                );
                const safeId = String(item.id || '').replace(/[^a-zA-Z0-9_-]/g, '');
                const safeTitle = escapeInlineArgText(item.pdf_title || 'Meeting_Documentation');
                return `
                <div class="report-card" style="animation-delay: ${index * 0.05}s;">
                    <div class="report-card-header">
                        <div class="report-icon">
                            <i class="fas ${fileIcon}"></i>
                        </div>
                        <div class="report-badge">
                            <i class="fas fa-check-circle"></i> ${formatLabel}
                        </div>
                    </div>
                    <div class="report-card-body">
                        <h4 class="report-title">${displayTitle}</h4>
                        <div class="report-meta">
                            <span><i class="fas fa-calendar"></i> ${vaEscapeHtml(formatDateIST(item.created_at))}</span>
                            <span><i class="fas fa-clock"></i> ${vaEscapeHtml(formatTimeIST(item.created_at))}</span>
                        </div>
                        <div class="report-video-info">
                            <i class="fas fa-video"></i> ${videoName}
                        </div>
                    </div>
                    <div class="report-card-footer">
                        ${hasReport ? `
                            <div class="report-actions-primary">
                                ${!isDocx ? `<button type="button" class="btn-report-action btn-view" onclick="viewHistoryReport('${safeId}', 'pdf')">
                                    <i class="fas fa-eye"></i> Preview
                                </button>` : ''}
                                <button type="button" class="btn-report-action btn-download" onclick="downloadHistoryReport('${safeId}', '${safeTitle}', '${exportFmt}')">
                                    <i class="fas fa-download"></i> Download
                                </button>
                                <button type="button" class="btn-report-action btn-delete" onclick="deleteVideoAnalysisReport('${safeId}', '${safeTitle}')">
                                    <i class="fas fa-trash-alt"></i> Delete
                                </button>
                            </div>
                            <div class="report-actions-secondary">
                                ${renderReportChatIndexStatus(item)}
                            </div>
                        ` : '<span class="report-processing"><i class="fas fa-spinner fa-spin"></i> Processing...</span>'}
                    </div>
                </div>
            `}).join('');
        } else {
            console.log('[VIDEO HISTORY] No reports found or invalid data structure');
            historyList.style.display = 'none';
            if (empty) empty.style.display = 'flex';
        }
    } catch (error) {
        console.error('[VIDEO HISTORY] Error loading history:', error);
        const loading = document.getElementById('reports-loading');
        if (loading) {
            loading.innerHTML = '<i class="fas fa-exclamation-triangle"></i><p>Error loading reports. Please try again.</p>';
            loading.style.color = '#dc3545';
        }
    } finally {
        isLoadingHistory = false;
    }
}

async function viewHistoryReport(historyId, exportFormat) {
    const format = (exportFormat || 'pdf').toLowerCase();
    if (format === 'docx') {
        showNotification('DOCX preview is not available in the browser. Use Download instead.', 'info');
        return;
    }
    return viewHistoryPDF(historyId);
}

async function downloadHistoryReport(historyId, reportTitle, exportFormat) {
    const format = (exportFormat || 'pdf').toLowerCase();
    const isDocx = format === 'docx';
    const endpoint = isDocx
        ? `/video-analysis/view-docx/${historyId}`
        : `/video-analysis/view-pdf/${historyId}`;
    const ext = isDocx ? 'docx' : 'pdf';

    const button = event?.target?.closest?.('.btn-download');
    const originalHTML = button ? button.innerHTML : '';

    try {
        if (button) {
            button.disabled = true;
            button.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
        }

        const token = window.authToken || localStorage.getItem('authToken');
        const response = await fetch(endpoint, {
            headers: { Authorization: `Bearer ${token}` },
        });

        if (!response.ok) {
            throw new Error(`Failed to download ${ext.toUpperCase()}`);
        }

        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const safeTitle = (reportTitle || 'Meeting_Documentation')
            .replace(/[^a-zA-Z0-9-_ ]/g, '_')
            .replace(/\s+/g, '_');
        a.download = `${safeTitle}.${ext}`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
        showNotification(`${ext.toUpperCase()} downloaded successfully!`, 'success');
    } catch (error) {
        console.error(`[VIDEO HISTORY] Error downloading ${ext}:`, error);
        showNotification(`Error downloading ${ext.toUpperCase()}`, 'error');
    } finally {
        if (button) {
            button.disabled = false;
            button.innerHTML = originalHTML;
        }
    }
}

async function viewHistoryPDF(historyId) {
    console.log('[VIDEO HISTORY] Opening PDF preview for:', historyId);
    
    const button = event.target.closest('.btn-view');
    const originalHTML = button ? button.innerHTML : '';
    
    try {
        // Show processing state
        if (button) {
            button.disabled = true;
            button.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
        }
        
        const modal = document.getElementById('pdf-preview-modal');
        const iframe = document.getElementById('pdf-preview-iframe');
        
        if (!modal || !iframe) {
            console.error('[VIDEO HISTORY] Modal or iframe not found');
            if (button) {
                button.disabled = false;
                button.innerHTML = originalHTML;
            }
            return;
        }
        
        // Get the PDF with authentication
        const token = window.authToken || localStorage.getItem('authToken');
        console.log('[VIDEO HISTORY] Fetching PDF with auth...');
        
        const response = await fetch(`/video-analysis/view-pdf/${historyId}`, {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`
            }
        });
        
        if (!response.ok) {
            throw new Error(`Failed to load PDF: ${response.status} ${response.statusText}`);
        }
        
        // Convert response to blob and create object URL
        const blob = await response.blob();
        const blobUrl = URL.createObjectURL(blob);
        
        console.log('[VIDEO HISTORY] PDF loaded, displaying in iframe');
        
        // Set iframe source to blob URL
        iframe.src = blobUrl;
        
        // Show modal
        modal.classList.remove('hidden');
        
        // Restore button state
        if (button) {
            button.disabled = false;
            button.innerHTML = originalHTML;
        }
        
        // Close button
        const closeBtn = document.getElementById('pdf-preview-close-btn');
        if (closeBtn) {
            closeBtn.onclick = () => {
                modal.classList.add('hidden');
                iframe.src = ''; // Clear iframe
                URL.revokeObjectURL(blobUrl); // Clean up blob URL
            };
        }
        
        // Click outside to close
        modal.onclick = (e) => {
            if (e.target === modal) {
                modal.classList.add('hidden');
                iframe.src = ''; // Clear iframe
                URL.revokeObjectURL(blobUrl); // Clean up blob URL
            }
        };
        
    } catch (error) {
        console.error('[VIDEO HISTORY] Error viewing PDF:', error);
        showNotification('Error loading PDF preview', 'error');
        // Restore button state on error
        if (button) {
            button.disabled = false;
            button.innerHTML = originalHTML;
        }
    }
}

async function downloadHistoryPDF(historyId, pdfTitle) {
    return downloadHistoryReport(historyId, pdfTitle, 'pdf');
}

async function deleteVideoAnalysisReport(historyId, pdfTitle) {
    // Confirm deletion
    if (
        !confirm(
            `Delete "${pdfTitle}"?\n\nThis permanently removes the PDF/DOCX file, meeting screenshots, chat search index, source video archive, and all related storage. This cannot be undone.`
        )
    ) {
        return;
    }
    
    const button = event.target.closest('.btn-delete');
    const originalHTML = button ? button.innerHTML : '';
    const reportCard = button ? button.closest('.report-card') : null;
    
    try {
        // Show processing state
        if (button) {
            button.disabled = true;
            button.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Deleting...';
        }
        
        const token = window.authToken || localStorage.getItem('authToken');
        // POST, not DELETE (VAPT: HTTP DELETE Method Enabled) — this call bypasses apiCall,
        // so the /delete suffix is spelled out here.
        const response = await fetch(`/video-analysis/delete/${encodeURIComponent(historyId)}/delete`, {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json'
            }
        });
        
        const data = await response.json();
        
        if (response.ok && data.success) {
            showNotification(
                'Report and all associated data deleted (file, frames, chat index, video).',
                'success'
            );
            if (typeof window.loadVideoAnalysisIndexedReports === 'function') {
                window.loadVideoAnalysisIndexedReports();
            }

            // Remove the card from UI with animation
            if (reportCard) {
                reportCard.style.opacity = '0';
                reportCard.style.transform = 'scale(0.9)';
                setTimeout(() => {
                    reportCard.remove();
                    
                    // Check if there are any reports left
                    const historyList = document.getElementById('video-history-list');
                    const empty = document.getElementById('reports-empty');
                    if (historyList && historyList.children.length === 0) {
                        historyList.style.display = 'none';
                        if (empty) empty.style.display = 'flex';
                    }
                }, 300);
            }
        } else {
            throw new Error(data.detail || data.message || 'Failed to delete report');
        }
        
    } catch (error) {
        console.error('[VIDEO HISTORY] Error deleting report:', error);
        showNotification(`Error: ${error.message}`, 'error');
        
        // Restore button state on error
        if (button) {
            button.disabled = false;
            button.innerHTML = originalHTML;
        }
    }
}


// ==============================================================================
// PDF SUCCESS MODAL
// ==============================================================================

function showExportSuccessModal(exportFormat, indexMeta = null) {
    const isDocx = exportFormat === 'docx';
    const modal = document.getElementById('pdf-success-modal');
    if (!modal) return;

    const titleEl = modal.querySelector('.modal-header h2');
    const iconEl = modal.querySelector('.success-message i');
    const messageEl = modal.querySelector('.modal-body .success-message p');
    if (titleEl) {
        titleEl.innerHTML = isDocx
            ? '<i class="fas fa-check-circle"></i> DOCX Generated Successfully!'
            : '<i class="fas fa-check-circle"></i> PDF Generated Successfully!';
    }
    if (iconEl) {
        iconEl.className = isDocx ? 'fas fa-file-word' : 'fas fa-file-pdf';
    }
    if (messageEl) {
        let msg = isDocx
            ? 'Your Word document has been generated and saved!'
            : 'Your PDF has been generated and saved!';
        if (indexMeta?.status === 'indexed') {
            msg += ` It is indexed for Chat with Reports (${indexMeta.frames || 0} screenshots, ${indexMeta.chunks || 0} sections). Open Chat with Reports to ask questions with images.`;
        } else if (indexMeta?.warning) {
            msg += ` Chat indexing note: ${indexMeta.warning} — use Reindex in View All Reports if needed.`;
        }
        messageEl.textContent = msg;
    }

    modal.classList.remove('hidden');
    
    // Close button
    const closeBtn = document.getElementById('pdf-success-close-btn');
    if (closeBtn) {
        closeBtn.onclick = () => {
            modal.classList.add('hidden');
            returnToVideoAnalysisMainScreen({ clearSession: false, notify: false });
        };
    }
    
    // Click outside to close
    modal.onclick = (e) => {
        if (e.target === modal) {
            modal.classList.add('hidden');
            returnToVideoAnalysisMainScreen({ clearSession: false, notify: false });
        }
    };
}

function showPDFSuccessModal() {
    showExportSuccessModal('pdf');
}

function goToModuleGenerator() {
    const modal = document.getElementById('pdf-success-modal');
    if (modal) {
        modal.classList.add('hidden');
    }
    switchView('curation');
    showNotification('Upload your generated PDF to create a training course', 'info');
}

function startOverFromSuccess() {
    const modal = document.getElementById('pdf-success-modal');
    if (modal) {
        modal.classList.add('hidden');
    }
    startOverVideoAnalysis();
}

function toggleHistoryPanel() {
    // Deprecated - now using modal
    openReportsModal();
}

function openReportsModal() {
    const modal = document.getElementById('all-reports-modal');
    const loading = document.getElementById('reports-loading');
    const historyList = document.getElementById('video-history-list');
    const empty = document.getElementById('reports-empty');
    
    if (!modal) return;
    
    // Show modal
    modal.classList.remove('hidden');
    modal.classList.add('show');
    
    // Show loading
    loading.style.display = 'flex';
    historyList.style.display = 'none';
    empty.style.display = 'none';
    
    // Load reports
    loadVideoAnalysisHistory();
    
    // Click outside to close
    modal.onclick = (e) => {
        if (e.target === modal) {
            closeReportsModal();
        }
    };
}

function closeReportsModal() {
    const modal = document.getElementById('all-reports-modal');
    if (modal) {
        modal.classList.remove('show');
        modal.classList.add('hidden');
        modal.onclick = null;
    }
}